mapper.select:
SELECT id, order_id AS orderId, `status`, pay_price AS payPrice, create_time AS createTime, pay_integral AS payIntegral, shipping_type AS shippingType FROM kx_store_order WHERE uid = #{userId}
and `status` in
#{item}
ORDER BY id DESC LIMIT #{offset}, #{limit}

SELECT tt.cate_id AS categoryId, tt.title AS categoryTitle, ifnull( sum( price ), 0 ) AS totalSalesVolume, count( 1 ) AS totalSales FROM ( SELECT spu.cate_id, t.pid, t.title AS cate_name, o.store_id, os.product_attr_id, os.product_id, os.product_title AS title, os.price FROM kx_store_order_product os LEFT JOIN kx_store_order o ON o.order_id = os.order_no LEFT JOIN kx_store_product spu ON os.product_id = spu.id LEFT JOIN ( SELECT c.id, c.pid, c.cate_name AS title FROM `kx_store_category` c WHERE c.pid = 0 ) t ON spu.cate_id = t.id WHERE o.STATUS IN ( 14, 16, 20, 30, 32, 34, 40, 50 ) AND TO_DAYS( o.update_time ) = TO_DAYS( NOW( ) )
AND o.store_id = #{storageId}
and o.store_id in
#{list}
) tt GROUP BY tt.pid, tt.title, tt.product_id ORDER BY totalSalesVolume, totalSales DESC LIMIT 10

SELECT tt.cate_id AS categoryId, tt.title AS categoryTitle, ifnull( sum( price ), 0 ) AS totalSalesVolume, count( 1 ) AS totalSales FROM ( SELECT spu.cate_id, t.pid, t.title AS cate_name, o.store_id, os.product_attr_id, os.product_id, os.product_title AS title, os.price FROM kx_store_order_product os LEFT JOIN kx_store_order o ON o.order_id = os.order_no LEFT JOIN kx_store_product spu ON os.product_id = spu.id LEFT JOIN ( SELECT c.id, c.pid, c.cate_name AS title FROM `kx_store_category` c WHERE c.pid = 0 ) t ON spu.cate_id = t.id WHERE o.STATUS IN ( 14, 16, 20, 30, 32, 34, 40, 50 ) AND TO_DAYS( o.update_time ) = TO_DAYS( NOW( ) )
AND o.store_id = #{storageId}
and o.store_id in
#{list}
) tt GROUP BY tt.pid, tt.title, tt.product_id, tt.product_attr_id, tt.cate_name, tt.price ORDER BY totalSalesVolume, totalSales DESC LIMIT 10

SELECT ifnull(sum(pay_price),0) totalSalesVolume,count(1) totalSales FROM kx_store_order o where o.status in (14,16,20,30,32,34,40,50)
AND o.store_id = #{storageId}
and o.store_id in
#{list}
and TO_DAYS(o.update_time) = TO_DAYS(NOW())

SELECT ifnull(sum(pay_price),0) totalSalesVolume,count(1) totalSales FROM kx_store_order o where o.status in (14,16,20,30,32,34,40,50)
AND o.store_id = #{storageId}
and o.store_id in
#{list}
and TO_DAYS( NOW( ) ) - TO_DAYS(o.update_time) = 1

SELECT ifnull(sum(pay_price),0) totalSalesVolume,count(1) totalSales  FROM kx_store_order o
where o.status in (14,16,20,30,32,34,40,50)

    AND o.store_id = #{storageId}


    and o.store_id in

        #{list}


and o.update_time BETWEEN #{start} and #{end}

SELECT DATE(o.create_time) AS orderDate, COUNT(*) AS totalSalesVolume, SUM(o.total_price) AS totalSalesAmount, SUM(o.coupon_price) AS totalCouponAmount, SUM(o.pay_price) AS actualPaymentAmount FROM kx_store_order o WHERE o.create_time BETWEEN #{startDate} AND #{endDate} AND o.is_del = 0 and o.status in (40,50)
and o.store_id = #{storageId}
GROUP BY DATE(o.create_time) -- 使用 DATE() 进行分组 ORDER BY DATE(o.create_time); -- 确保排序也按日期

SELECT DATE(a.create_time) AS date,
SUM(a.pay_price) AS content, b.name as storageName FROM kx_store_order a left join kx_storage b on b.id = a.store_id WHERE a.create_time BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(a.create_time),a.store_id ORDER BY DATE(a.create_time);
